        <div class="portal-columns"><section class="portal-card"><div class="card-heading"><div><span class="eyebrow eyebrow-dark">NOTIFICATIONS</span><h2>Stay in the loop</h2></div><form action="<?= site_url('portal/notifications/read') ?>" method="post"><?= csrf_field() ?><button class="text-button" type="submit">Mark personal alerts read</button></form></div><?php if (!$notifications): ?><p class="empty-state">No service updates yet.</p><?php else: ?><?php foreach ($notifications as $item): ?><article class="message-item <?= $item['read_at'] ? '' : 'is-unread' ?>"><strong><?= esc($item['title']) ?></strong><small><?= esc(date('M j, Y · g:i A', strtotime($item['created_at']))) ?></small><p><?= esc($item['body']) ?></p></article><?php endforeach ?><?php endif ?></section><section class="portal-card"><div class="card-heading"><div><span class="eyebrow eyebrow-dark">SUN SON SOLAR</span><h2>Company updates</h2></div></div><?php if (!$announcements): ?><p class="empty-state">Announcements and offers will appear here.</p><?php else: ?><?php foreach ($announcements as $item): ?><article class="message-item"><strong><?= esc($item['title']) ?></strong><small><?= esc(date('M j, Y', strtotime($item['created_at']))) ?></small><p><?= nl2br(esc($item['body'])) ?></p></article><?php endforeach ?><?php endif ?></section></div>
    <?php endif ?>

    <section class="portal-columns profile-bottom"><section class="portal-card"><div class="card-heading"><div><span class="eyebrow eyebrow-dark">MY ACCOUNT</span><h2>Personal details</h2></div></div><p class="profile-summary"><strong><?= esc(trim($user['first_name'] . ' ' . ($user['middle_name'] ?? '') . ' ' . $user['last_name'])) ?></strong><span><?= esc($user['email']) ?></span><span><?= esc($user['phone']) ?></span><span><?= esc($user['address']) ?></span></p></section><?php if ($user['role'] !== 'customer'): ?><section class="portal-card"><div class="card-heading"><div><span class="eyebrow eyebrow-dark">ANNOUNCEMENTS</span><h2>Team inbox</h2></div></div><?php if (!$announcements): ?><p class="empty-state">No team announcements right now.</p><?php else: ?><?php foreach ($announcements as $item): ?><article class="message-item"><strong><?= esc($item['title']) ?></strong><small><?= esc(date('M j, Y', strtotime($item['created_at']))) ?></small><p><?= nl2br(esc($item['body'])) ?></p></article><?php endforeach ?><?php endif ?></section><?php endif ?></section>
</main>
<script>
document.querySelectorAll('[data-checkin-form]').forEach(function (form) {
    form.addEventListener('submit', function (event) {
        if (form.dataset.ready === 'yes') return;
        event.preventDefault();
        var button = form.querySelector('button');
        button.disabled = true;
        button.textContent = 'Getting your location…';
        if (!navigator.geolocation) { button.disabled = false; button.textContent = 'Location is unavailable'; return; }
        navigator.geolocation.getCurrentPosition(function (position) {
            form.querySelector('[name="latitude"]').value = position.coords.latitude;
            form.querySelector('[name="longitude"]').value = position.coords.longitude;
            form.dataset.ready = 'yes';
            form.requestSubmit();
        }, function () { button.disabled = false; button.textContent = 'Allow location to check in'; }, { enableHighAccuracy: true, timeout: 12000, maximumAge: 0 });
    });
});
</script>
</body>
</html>
